-- Dados iniciais/importados dos formulários de defeito.
-- Execute este arquivo depois do database/schema.sql somente se quiser carregar os registros OCR.

on conflict (id) do update set mes=excluded.mes,data=excluded.data,placa=excluded.placa,motorista=excluded.motorista,defeito=excluded.defeito,localizacao=excluded.localizacao,gravidade=excluded.gravidade,status=excluded.status,responsavel=excluded.responsavel,obs=excluded.obs,anexo=excluded.anexo,pagina=excluded.pagina;
